  lists: () => [...taskKeys.all, "list"] as const,
  list: (query: TaskListQuery) => [...taskKeys.lists(), query] as const,
  details: () => [...taskKeys.all, "detail"] as const,
  detail: (id: string) => [...taskKeys.details(), id] as const,
};

import { queryOptions } from "@tanstack/react-query";
import { fetchTask, fetchTasks, type TaskListQuery } from "@/lib/api/tasks";
import { taskKeys } from "./task-keys";

export function taskListOptions(query: TaskListQuery) {
  return queryOptions({
    queryKey: taskKeys.list(query),
    queryFn: () => fetchTasks(query),
    staleTime: 30_000,
  });
}

export function taskDetailOptions(id: string) {
  return queryOptions({
    queryKey: taskKeys.detail(id),
    queryFn: () => fetchTask(id),
    staleTime: 30_000,
  });
}
